/**
 * The drawings of the four seasons: the forest and the botanical plate.
 *
 * The geometry of the Herbier seasons mock-up, taken from its SVG as the drawing
 * script is lost. Each season plants its own trees — spruce, round trees, round
 * trees in bloom, spruce under snow — and draws its own plate: a fern in bud, a
 * daisy, a leaf, a fern under snow.
 *
 * As everywhere in the package a drawing is a mask painted in a theme colour. A tree
 * is two masks: its body, painted in the colour of its plane, and its trim (the
 * blossoms, the snow), painted in the season's accent. A plate is one mask per
 * colour it uses. Constants and pure functions only: a style file imports no module.
 */

import { FOREST_FRAME, PLATE_FRAME } from './art.style.ts';

export type Season = 'spring' | 'summer' | 'autumn' | 'winter';

/** The trees: 0 spruce, 1 round, 2 round in bloom, 3 spruce under snow. */
export type TreeKind = 0 | 1 | 2 | 3;

/** `[kind, x, y, scale]`, near the horizon first, on the 1200 wide frame. */
export type Tree = readonly [TreeKind, number, number, number];

export type Plane = 'back' | 'ridge' | 'middle' | 'near' | 'front';

export const PLANES: readonly Plane[] = ['back', 'ridge', 'middle', 'near', 'front'];

