const svg = (viewBox: string, body: string): string =>
  `data:image/svg+xml,${encodeURIComponent(
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${viewBox}">${body}</svg>`,
  )}`;

/** A mask of nothing: what a season has in the place of a drawing it does not use. */
export const NO_MASK = svg('0 0 1 1', '');

const FRAME = `0 ${FOREST_FRAME.top} ${FOREST_FRAME.width} ${FOREST_FRAME.height}`;

const place = (trees: readonly Tree[], symbol: (kind: TreeKind) => string): string =>
  trees
    .map(([kind, x, y, scale]) => `<use href="#${symbol(kind)}" transform="translate(${x} ${y}) scale(${scale})"/>`)
    .join('');

/** The bodies of the trees of one plane of one season: black, the colour comes from the theme. */
export const treeMask = (season: Season, plane: Plane): string => {
  const trees = SEASON_FOREST[season][plane];
  const kinds = [...new Set(trees.map(([kind]) => kind))];
  return svg(
    FRAME,
    `<defs>${kinds.map((kind) => `<g id="k${kind}" fill="#000">${TREE_BODY[kind]}</g>`).join('')}</defs>${place(trees, (kind) => `k${kind}`)}`,
  );
};

/** The blossoms or the snow of one plane, or nothing when the season has none. */
export const trimMask = (season: Season, plane: Plane): string => {
  const trees = SEASON_FOREST[season][plane].filter(([kind]) => kind === 2 || kind === 3);
  if (trees.length === 0) return NO_MASK;
  const kinds = [...new Set(trees.map(([kind]) => kind))] as (2 | 3)[];
  return svg(
    FRAME,
    `<defs>${kinds.map((kind) => `<g id="t${kind}" fill="#000">${TREE_TRIM[kind]}</g>`).join('')}</defs>${place(trees, (kind) => `t${kind}`)}`,
  );
};

/** One colour of a season's plate, or nothing when the plate does not use it. */
export const seasonPlateMask = (season: Season, pass: PlatePass): string => {
  const markup = SEASON_PLATE[season][pass];
  return markup ? svg(`0 0 ${PLATE_FRAME.width} ${PLATE_FRAME.height}`, markup) : NO_MASK;
};
